  // 1–4 Strategic & governance
  d('strategic', 'Strategic risk', 'strategy', 'Risk that business model, market position or major decisions fail to deliver objectives.', 'Frames counterparty viability, concentration and long-term supplier/insurer relationships.', { sub: ['Business model', 'Competitive disruption', 'M&A integration', 'Concentration'], ev: ['Annual reports', 'Material 8-K events', 'Segment disclosures'], ins: ['D&O'], proc: ['Strategic sourcing'] });
