  d('bribery-aml-sanctions', 'Bribery, corruption, AML & sanctions risk', 'integrity', 'Risk of involvement in bribery, money laundering, terrorist financing or sanctions breaches.', 'Strict-liability regimes make counterparty and jurisdiction screening essential; RYLAQ only links to official lists.', { sub: ['Sanctions exposure', 'PEP exposure', 'Bribery', 'Money laundering', 'Debarment'], ev: ['Official sanctions lists (link-out)', 'Debarment lists', 'Enforcement releases', 'WGI control-of-corruption'], ins: ['Political risk', 'Trade credit'], proc: ['Due diligence', 'Integrity pacts'], src: ['federalRegister', 'worldbank', 'courtlistener'], aliases: ['sanctions risk', 'aml risk', 'bribery risk', 'corruption risk', 'money laundering', 'debarment', 'sanctions'] });
  // 7–13 Legal/regulatory/compliance/tax
