  d('tax', 'Tax risk', 'legal', 'Risk from tax disputes, changes in tax law or aggressive tax positions.', 'Tax disputes can weaken counterparties; RYLAQ does not provide tax advice.', { sub: ['Tax disputes', 'Tax law change', 'Withholding'], ev: ['Public filings (tax contingencies)', 'Regulatory documents'], dirs: ['regulatory'] });
