  d('customs-valuation', 'Customs-valuation risk', 'legal', 'Risk that declared customs values, origin or classification are challenged.', 'Affects landed cost, duties and penalties across supply chains.', { sub: ['Valuation', 'Origin', 'Classification'], ev: ['Tariff schedules', 'Customs rulings'], dirs: ['trade'], std: ['WTO Customs Valuation Agreement'] });
