  d('process', 'Process risk', 'operational', 'Risk from poorly designed or executed business processes.', 'Quality failures at suppliers show up in recalls and warning letters.', { sub: ['Quality', 'Execution errors'], ev: ['Recalls', 'Regulatory notices'] });
