  d('disaster-recovery', 'Disaster-recovery risk', 'operational', 'Risk that IT and data cannot be restored within tolerance after disruption.', 'Vendor DR capability matters for critical outsourcing.', { sub: ['RTO/RPO failure', 'Backup failure'], ev: ['Standards link-outs'], std: ['ISO/IEC 27031', 'ISO 22301'], ins: ['Cyber', 'Business interruption'], aliases: ['disaster recovery', 'dr'] });
